(function(document) {
  "use strict";

  /**
   * Applies the UHF layout container ID based on the skip link href.
   */
  const applyUhfLayoutContainerId = () => {
    // Selectors.
    const layoutContainerSelector = '.microsoft-template-layout-container';
    const uhfSelector = '#uhfSkipToMain, .uhf-skip-link';
    const acomSelector = '.azure-skip-nav';

    // Content IDs.
    const defaultContentId = 'mainContent';
    const defaultAcomContentId = 'main';

    // Get the skip link element from the DOM (Azure or standard UHF).
    const layoutContainer = document.querySelector(layoutContainerSelector);
    const uhfSkipToMain = document.querySelector(uhfSelector);
    const acomHeaderSkipToMain = document.querySelector(acomSelector);
    const skipLinkElement = uhfSkipToMain || acomHeaderSkipToMain;
    
    if (!skipLinkElement || !layoutContainer) {
      // Either no skip link or no layout container found, no need to continue.
      return;
    }
    
    let targetId = uhfSkipToMain ? defaultContentId : defaultAcomContentId;
    const layoutContainerId = layoutContainer?.getAttribute("id");
    const skipLinkAttribute = skipLinkElement.hasAttribute("data-href") ? "data-href" : "href";
    
    const skipLinkHref = skipLinkElement.getAttribute(skipLinkAttribute)?.split("#").pop(); // Get the part after the '#' if it exists.
    if (skipLinkHref) {
      targetId = skipLinkHref;
    } else if (layoutContainerId) {
      targetId = layoutContainerId;
    }
    skipLinkElement.setAttribute(skipLinkAttribute, `#${targetId}`);
    layoutContainer.setAttribute("id", targetId);
  };

  // Apply the layout container ID on page load.
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applyUhfLayoutContainerId);
  } else {
    applyUhfLayoutContainerId();
  }
})(document);
